<?php
declare(strict_types=1);
namespace App\Modules\FreshFood\Models;
use App\Core\Database;
final class FreshFoodCategory {private Database $db;public function __construct(){$this->db=app()->get('db');}public function all(int $t,bool $trash=false):array{$w=$trash?'c.deleted_at IS NOT NULL':'c.deleted_at IS NULL';return $this->db->fetchAll("SELECT c.*,b.name business_name,(SELECT COUNT(*) FROM fresh_food_products p WHERE p.category_id=c.id AND p.deleted_at IS NULL) product_count FROM fresh_food_categories c JOIN fresh_food_profiles f ON f.id=c.fresh_food_id JOIN businesses b ON b.id=f.business_id WHERE c.tenant_id=? AND {$w} ORDER BY c.fresh_food_id,c.sort_order,c.id",[$t]);}public function restaurants(int $t):array{return $this->db->fetchAll("SELECT id,business_name FROM (SELECT f.id,b.name business_name FROM fresh_food_profiles f JOIN businesses b ON b.id=f.business_id WHERE f.tenant_id=? AND f.deleted_at IS NULL AND b.deleted_at IS NULL) x ORDER BY business_name",[$t]);}public function find(int $t,int $id):?array{return $this->db->fetch("SELECT c.*,b.name business_name FROM fresh_food_categories c JOIN fresh_food_profiles f ON f.id=c.fresh_food_id JOIN businesses b ON b.id=f.business_id WHERE c.tenant_id=? AND c.id=? AND c.deleted_at IS NULL LIMIT 1",[$t,$id]);}public function findDeleted(int $t,int $id):?array{return $this->db->fetch("SELECT c.* FROM fresh_food_categories c WHERE c.tenant_id=? AND c.id=? AND c.deleted_at IS NOT NULL LIMIT 1",[$t,$id]);}public function businessExists(int $t,int $id):bool{return $this->db->fetch("SELECT id FROM fresh_food_profiles WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$t,$id])!==null;}public function create(int $t,array $d,int $u):int{$this->db->execute("INSERT INTO fresh_food_categories(uuid,tenant_id,fresh_food_id,name,description,sort_order,status,created_by,updated_by) VALUES(UUID(),?,?,?,?,?,?,?,?)",[$t,$d['fresh_food_id'],$d['name'],$d['description'],$d['sort_order'],$d['status'],$u,$u]);return(int)$this->db->lastInsertId();}public function update(int $t,int $id,array $d,int $u):void{$this->db->execute("UPDATE fresh_food_categories SET fresh_food_id=?,name=?,description=?,sort_order=?,status=?,updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$d['fresh_food_id'],$d['name'],$d['description'],$d['sort_order'],$d['status'],$u,$t,$id]);}public function delete(int $t,int $id,int $u):void{$this->db->execute("UPDATE fresh_food_categories SET deleted_at=NOW(),updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$u,$t,$id]);}public function restore(int $t,int $id,int $u):void{$this->db->execute("UPDATE fresh_food_categories SET deleted_at=NULL,updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NOT NULL",[$u,$t,$id]);}}
